const ATENDENTES_IDS = [
  '668d7fdd0c342f9bf23176c5', // Nadja Ferreira
  '680f9b99836e64904f92f5ce', // Livanir
  '662f87616864d033eebd6411', // Jamilly Sousa
  '68b5c2f62526439c8f281d8d', // Georgia Wortmam
];
const THRESHOLDS = {
  '5bf73d1d186f7d2b0d647a60': 2,   // Comercial
  '5bf73d1d186f7d2b0d647a61': 4,   // Suporte
  '5d1624085e74a002308aa25e': 6,   // Financeiro
  '5d1629315e74a002308aa262': 8,   // Renegociacoes
  'default': 4,
};
const NOMES_SETOR = {
  '5bf73d1d186f7d2b0d647a60': 'Comercial',
  '5bf73d1d186f7d2b0d647a61': 'Suporte',
  '5d1624085e74a002308aa25e': 'Financeiro',
  '5d1629315e74a002308aa262': 'Renegociacoes',
};
const tickets = $input.first().json?.data ?? [];
const agora = new Date();
const esquecidos = [];
for (const ticket of tickets) {
  const abertoEm = new Date(ticket.date);
  const horas = (agora - abertoEm) / 3600000;
  const threshold = THRESHOLDS[ticket.setor] ?? THRESHOLDS.default;
  if (horas >= threshold) {
    const setor = NOMES_SETOR[ticket.setor] ?? 'Desconhecido';
    const h = horas.toFixed(1);
    esquecidos.push({ json: {
      atendimentoId: ticket._id,
      protocolo: ticket.protocolo ?? '',
      setor,
      setorId: ticket.setor ?? '',
      horasAberto: parseFloat(h),
      threshold,
      atendentesParaNotificar: ATENDENTES_IDS,
      mensagemNotificacao: `Ticket esquecido: ${ticket.protocolo} | ${setor} | ${h}h`,
      mensagemObservacao: `[N8N ALERTA] Ticket aberto ha ${h}h (limite: ${threshold}h). Verificar e dar retorno.`,
    }});
  }
}
console.log(`[ALERTA] Tickets esquecidos: ${esquecidos.length}`);
return esquecidos.length ? esquecidos : [];

