const body = $input.first().json.body ?? $input.first().json;

function normalizeDocument(value) {
  return (value ?? '').toString().replace(/\D/g, '');
}

function extractDocumentFromText(text) {
  const normalized = normalizeDocument(text);
  if (normalized.length === 11 || normalized.length === 14) return normalized;
  const matches = (text ?? '').toString().match(/\d[\d.\/-]{10,20}\d/g) ?? [];
  for (const match of matches) {
    const digits = normalizeDocument(match);
    if (digits.length === 11 || digits.length === 14) return digits;
  }
  return '';
}

function buildPhoneLookup(rawPhone) {
  const digits = (rawPhone ?? '').toString()
    .replace(/@c\.us$/, '')
    .replace(/@s\.whatsapp\.net$/, '')
    .replace(/\D/g, '');
  const local = digits.startsWith('55') ? digits.slice(2) : digits;
  const ddd = local.slice(0, 2);
  const numero = local.slice(2);
  const hPos = numero.length >= 9 ? 5 : 4;
  const searchPhone = numero ? numero.slice(0, hPos) + '-' + numero.slice(hPos) : '';
  return { digits, local, ddd, numero, searchPhone };
}

