  const local = digits.startsWith('55') ? digits.slice(2) : digits;
  const ddd = local.slice(0, 2);
  const numero = local.slice(2);
  const hPos = numero.length >= 9 ? 5 : 4;
  const searchPhone = numero ? numero.slice(0, hPos) + '-' + numero.slice(hPos) : '';
  return { digits, local, ddd, numero, searchPhone };
}

const atendimentoId = (body.atendimentoId ?? body.atendimento?._id ?? body.id ?? '').toString();
const telefoneRaw = (body.telefone ?? body.phone ?? body.contact?.phone ?? body.from ?? '').toString();
const messageText = (body.mensagem?.texto ?? body.texto ?? '').toString();
const documentoInformado = (
  body.cpf_cnpj ?? body.cpfCnpj ?? body.documento ?? body.document ?? body.cpf ?? body.cnpj ?? ''
).toString();
const documento = normalizeDocument(documentoInformado) || extractDocumentFromText(messageText);
const phone = buildPhoneLookup(telefoneRaw);
const useDocument = documento.length === 11 || documento.length === 14;
const lookupField = useDocument ? 'cliente.cnpj_cpf' : 'cliente.whatsapp';
const lookupQuery = useDocument ? formatDocument(documento) : phone.searchPhone;
const lookupOper = useDocument ? '=' : 'L';
console.log(`[R5] modo: ${useDocument ? 'documento' : 'telefone'} | query: ${lookupQuery} | atendimento: ${atendimentoId}`);
return [{ json: { atendimentoId, telefoneRaw, ddd: phone.ddd, numero: phone.numero, searchPhone: phone.searchPhone, messageText, documento, documentoTipo: documento.length === 14 ? 'CNPJ' : documento.length === 11 ? 'CPF' : '', lookupMode: useDocument ? 'documento' : 'telefone', lookupField, lookupQuery, lookupOper } }];

const raw = $input.first().json ?? {};
let parsed;
try {
  parsed = typeof raw.data === 'string' ? JSON.parse(raw.data) : (raw.data ?? raw);
} catch (error) {
  parsed = raw.data ?? raw;
}

const registros = Array.isArray(parsed?.registros) ? parsed.registros : [];
if (!registros.length) return [];
const client = registros[0];
const atendimentoId = $('R5 - Extrair Telefone').first().json.atendimentoId;
return [{ json: {
  atendimentoId,
  clienteId:      client.id,
  clienteNome:    client.razao || client.fantasia || 'Desconhecido',
  clienteCpfCnpj: client.cnpj_cpf || '',
}}];

const result    = $input.first().json;
const registros = result.data?.registros ?? result.registros ?? [];
const extrair   = $('R5 - Extrair Dados').first().json;

if (!registros.length) {
  return [{ json: {
    tem_contrato: false,
    atendimentoId: extrair.atendimentoId,
    clienteNome:   extrair.clienteNome,
    clienteId:     extrair.clienteId,
    status:        'DESCONHECIDO',
  }}];
}

// Prioridade: BL (bloqueado) > FA (fin. atraso) > A (ativo) > CA (cancelado)
const prio = { BL: 0, FA: 1, A: 2, CA: 3 };
const ordenados = [...registros].sort((a, b) =>
  (prio[a.status] ?? 99) - (prio[b.status] ?? 99)
);
const contrato = ordenados[0];

console.log(`[R5] Cliente: ${extrair.clienteNome} | Contrato status: ${contrato.status} | Login: ${contrato.login}`);

return [{ json: {
  tem_contrato:    true,
  atendimentoId:   extrair.atendimentoId,
  clienteNome:     extrair.clienteNome,
  clienteId:       extrair.clienteId,
  contratoId:      contrato.id,
  contratoLogin:   contrato.login ?? '',
  status:          contrato.status,  // BL, FA, A, CA
  plano:           contrato.contrato ?? '',
}}];

