const staticData = $getWorkflowStaticData('global');
staticData.hybridInput = staticData.hybridInput ?? {};
staticData.hybridInput.pendingDocuments = staticData.hybridInput.pendingDocuments ?? {};

function normalizeDocument(value) {
  return (value ?? '').toString().replace(/\D/g, '');
}

const origem = $('R5 - Extrair Telefone').first().json ?? {};
const atendimentoId = (origem.atendimentoId ?? '').toString();
const documento = normalizeDocument(origem.documento ?? '');

if (atendimentoId && !documento) {
  staticData.hybridInput.pendingDocuments[atendimentoId] = {
    intent: 'diagnostico',
    createdAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + (24 * 60 * 60 * 1000)).toISOString(),
  };
}

return [{
  json: {
    atendimentoId,
    msgTexto: documento
      ? 'Nao localizei cadastro com o CPF ou CNPJ informado. Confira os numeros e me envie novamente, por favor.'
      : 'Para eu verificar sua conexao e continuar com o atendimento, me informe o CPF ou CNPJ do titular, por favor.',
  },
  pairedItem: 0,
}];

const item = $input.first().json ?? {};
const messageText = (item.messageText ?? item.texto ?? item.mensagem?.texto ?? '').toString().trim();
const source = (item.source ?? '').toString().toLowerCase();
let operationalText = 'Posso te ajudar por aqui. Me informe o CPF ou CNPJ do titular para localizar seu cadastro.';
if (source === 'opa_flow' && (/^teste$/i.test(messageText) || !messageText)) {
  operationalText = 'Perfeito. Vamos iniciar seu atendimento. Me informe o CPF ou CNPJ do titular para eu localizar o cadastro.';
}
return [{
  json: {
    ...item,
    atendimentoId: item.atendimentoId ?? item.customerServiceId ?? '',
    customerServiceId: item.customerServiceId ?? item.atendimentoId ?? '',
    operationalText,
  },
  pairedItem: 0,
}];

function extractText(payload) {
  const msg = payload?.mensagem;
  if (typeof msg === 'string') return msg.trim();
  if (msg && typeof msg.texto === 'string') return msg.texto.trim();
  if (msg && typeof msg.titulo === 'string') return msg.titulo.trim();
  return (
    payload?.message?.content?.text ??
    payload?.message?.text ??
    payload?.texto ??
    ''
  ).toString().trim();
}

function normalizeDocument(value) {
  return (value ?? '').toString().replace(/\D/g, '');
}

function extractDocument(payload, text) {
  const explicit = normalizeDocument(
    payload?.cpf_cnpj ?? payload?.cpfCnpj ?? payload?.documento ?? payload?.document ?? payload?.cpf ?? payload?.cnpj ?? ''
  );
  if (explicit.length === 11 || explicit.length === 14) return explicit;

  const normalizedText = normalizeDocument(text);
  if (normalizedText.length === 11 || normalizedText.length === 14) return normalizedText;

  const matches = (text ?? '').toString().match(/\d[\d.\/-]{10,20}\d/g) ?? [];
  for (const match of matches) {
    const digits = normalizeDocument(match);
    if (digits.length === 11 || digits.length === 14) return digits;
  }

  return '';
}

function classifyEvent(explicitEvent, text) {
  const directEventMap = {
    transferencia: 'transferencia',
    transferencia_humano: 'transferencia',
    segunda_via: 'segunda_via',
    financeiro: 'segunda_via',
    diagnostico: 'diagnostico',
    suporte: 'diagnostico',
    verification: 'verification',
  };

  const explicit = (explicitEvent ?? '').toString().trim().toLowerCase();
  if (directEventMap[explicit]) return directEventMap[explicit];

  const normalizedText = (text ?? '').toString().toLowerCase();
  const financeRegex = /(2\s*via|segunda\s*via|boleto|pix|fatura|linha\s+digit[aá]vel|c[oó]digo\s+pix|copia\s+e\s+cola|copiar\s+e\s+colar)/i;
  if (financeRegex.test(normalizedText)) return 'segunda_via';

  const supportRegex = /(sem\s+internet|sem\s+conex[aã]o|sem\s+sinal|sem\s+acesso|internet\s+caiu|lentid[aã]o|lenta|inst[aá]vel|oscila)/i;
  if (supportRegex.test(normalizedText)) return 'diagnostico';

  return 'nova_mensagem';
}

const input = $input.first().json ?? {};
const incoming = input.body ?? input.rawPayload ?? input;
const rawEvent = incoming?.event?.type ?? incoming?.event ?? incoming?.eventType ?? input?.event ?? input?.eventType;
const messageText = extractText(incoming);
const documento = extractDocument(incoming, messageText);
const atendimentoId = (
  incoming.atendimentoId ??
  incoming.customerServiceId ??
  incoming.id_rota ??
  incoming.atendimento?._id ??
  incoming.id ??
  ''
).toString();
const contactPhone = (
  incoming.telefone ??
  incoming.contactPhoneRaw ??
  incoming.contactPhone ??
  incoming.contato?.celularCompleto ??
  incoming.contact?.phone ??
  incoming.from ??
  ''
).toString().trim();
const contactName = (
  incoming.contato?.nome ??
  incoming.contact?.name ??
  incoming.contactName ??
  'Desconhecido'
).toString();
const source = (
  incoming.source ??
  input.source ??
  'webhook'
).toString();
const messageTimestamp = (
  incoming.messageTimestamp ??
  incoming.createdAt ??
  incoming.data ??
  new Date().toISOString()
).toString();
const messageId = (
  incoming.messageId ??
  incoming.pollMessageId ??
  incoming._id ??
  ''
).toString();
const event = classifyEvent(rawEvent, messageText);

const body = {
  ...incoming,
  event,
  eventType: event,
  atendimentoId,
  customerServiceId: atendimentoId,
  telefone: contactPhone,
  contactPhoneRaw: contactPhone,
  cpf_cnpj: incoming.cpf_cnpj ?? incoming.cpfCnpj ?? incoming.documento ?? incoming.document ?? incoming.cpf ?? incoming.cnpj ?? (documento || undefined),
  documento: documento || undefined,
  contato: {
    ...(incoming.contato ?? {}),
    nome: contactName,
    celularCompleto: contactPhone,
  },
  contact: {
    ...(incoming.contact ?? {}),
    name: contactName,
    phone: contactPhone,
  },
  mensagem: (
    incoming.mensagem && typeof incoming.mensagem === 'object'
      ? { ...incoming.mensagem, texto: messageText || incoming.mensagem.texto || '' }
      : { texto: messageText }
  ),
  texto: messageText,
  source,
  messageTimestamp,
  messageId,
};

return [{
  json: {
    ...body,
    body,
    rawPayload: incoming,
    source,
    event,
    eventType: event,
    messageText,
    messageTimestamp,
    messageId,
    atendimentoId,
    customerServiceId: atendimentoId,
    contactName,
    contactPhoneRaw: contactPhone,
    documento,
    documentoTipo: documento.length === 14 ? 'CNPJ' : documento.length === 11 ? 'CPF' : '',
    isPollingReplay: source === 'polling',
  },
  pairedItem: 0,
}];

const staticData = $getWorkflowStaticData('global');
staticData.hybridInput = staticData.hybridInput ?? {
  processed: {},
  lastPollingSeenAt: null,
};

const state = staticData.hybridInput;
const nowIso = new Date().toISOString();
const ttlMs = 72 * 60 * 60 * 1000;
const now = Date.now();

for (const [key, meta] of Object.entries(state.processed ?? {})) {
  const seenAt = meta?.seenAt ? Date.parse(meta.seenAt) : 0;
  if (!seenAt || now - seenAt > ttlMs) {
    delete state.processed[key];
  }
}

function fallbackKey(json) {
  const parts = [
    (json.source ?? 'unknown').toString(),
    (json.customerServiceId ?? '').toString(),
    (json.messageTimestamp ?? '').toString(),
    (json.contactPhoneRaw ?? '').toString(),
    (json.messageText ?? '').toString().trim().toLowerCase(),
  ];
  return `fallback:${parts.join('|')}`;
}

const output = [];
const items = $input.all();

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const json = item.json ?? {};
  const dedupeKey = (json.messageId ? `msg:${json.messageId}` : fallbackKey(json)).trim();
  if (!dedupeKey || state.processed[dedupeKey]) {
    continue;
  }

  state.processed[dedupeKey] = {
    seenAt: nowIso,
    source: (json.source ?? 'unknown').toString(),
    event: (json.event ?? json.eventType ?? '').toString(),
    customerServiceId: (json.customerServiceId ?? '').toString(),
  };

  if ((json.source ?? '').toString() === 'polling') {
    const candidate = Date.parse((json.messageTimestamp ?? '').toString());
    if (!Number.isNaN(candidate)) {
      const current = state.lastPollingSeenAt ? Date.parse(state.lastPollingSeenAt) : 0;
      if (!current || candidate > current) {
        state.lastPollingSeenAt = new Date(candidate).toISOString();
      }
    }
  }

  output.push({
    json: {
      ...json,
      dedupeKey,
    },
    pairedItem: item.pairedItem ?? index,
  });
}

return output;

const BOT_ATENDENTE_ID = '681d1984167b6a3e83129114';
const staticData = $getWorkflowStaticData('global');
const state = staticData.hybridInput ?? {};
const pendingSources = [
  state.pendingDocuments ?? {},
  state.pendingContracts ?? {},
  state.pendingChoices ?? {},
  state.contractChoices ?? {},
];
const trackedIds = new Set();
const trackedProtocols = new Set();

function remember(value) {
  const text = (value ?? '').toString().trim();
  if (!text) return;
  if (/^[a-f0-9]{24}$/i.test(text)) trackedIds.add(text);
  if (/^VIP\d+/i.test(text)) trackedProtocols.add(text);
}

for (const source of pendingSources) {
  for (const [key, entry] of Object.entries(source)) {
    remember(key);
    if (entry && typeof entry === 'object') {
      remember(entry.atendimentoId);
      remember(entry.customerServiceId);
      remember(entry.routeId);
      remember(entry.protocolo);
      remember(entry.protocol);
    }
  }
}

const response = $input.first().json ?? {};
const atendimentos = Array.isArray(response.data) ? response.data : [];
const now = Date.now();
const RECENT_WINDOW_MS = 45 * 60 * 1000;

function toTimestamp(item) {
  for (const candidate of [item?.updatedAt, item?.update, item?.lastMessageAt, item?.data_ultima_interacao, item?.date]) {
    const ts = Date.parse((candidate ?? '').toString());
    if (!Number.isNaN(ts) && ts > 0) return ts;
  }
  return 0;
}

function isTracked(item) {
  const id = (item?._id ?? '').toString();
  const protocolo = (item?.protocolo ?? '').toString();
  return trackedIds.has(id) || trackedProtocols.has(protocolo);
}

function isRecent(item) {
  const ts = toTimestamp(item);
  return !!ts && (now - ts) <= RECENT_WINDOW_MS;
}

const scoped = atendimentos.filter((item) => (item?.id_atendente ?? '').toString() === BOT_ATENDENTE_ID);
const tracked = scoped.filter(isTracked).sort((a, b) => toTimestamp(b) - toTimestamp(a));
const recent = scoped.filter((item) => !isTracked(item) && isRecent(item)).sort((a, b) => toTimestamp(b) - toTimestamp(a));
const selected = tracked.length ? tracked : recent.slice(0, 5);

return selected.map((item, index) => ({
  json: {
    source: 'polling',
    pollRouteId: (item?._id ?? '').toString(),
    pollProtocolo: (item?.protocolo ?? '').toString(),
    pollTracked: isTracked(item),
    pollActivityAt: toTimestamp(item) ? new Date(toTimestamp(item)).toISOString() : '',
    pollIndex: index,
    rawAtendimento: item,
  },
  pairedItem: 0,
}));

function extractText(message) {
  if (typeof message?.mensagem === 'string') return message.mensagem.trim();
  if (typeof message?.mensagem?.texto === 'string') return message.mensagem.texto.trim();
  if (typeof message?.mensagem?.titulo === 'string') return message.mensagem.titulo.trim();
  return '';
}

function isInbound(message) {
  return (!!message?.id_user && !message?.id_atend) || message?.tipoDestinatario === 'usuarios';
}

function normalizeDocument(value) {
  return (value ?? '').toString().replace(/\D/g, '');
}

function classifyEvent(text) {
  const normalized = (text ?? '').toString().toLowerCase();
  const financeRegex = /(2\s*via|segunda\s*via|boleto|pix|fatura|linha\s+digit[aã]vel|c[oó]digo\s+pix|copia\s+e\s+cola|copiar\s+e\s+colar)/i;
  if (financeRegex.test(normalized)) return 'segunda_via';

  const supportRegex = /(sem\s+internet|sem\s+conex[aã]o|sem\s+sinal|sem\s+acesso|internet\s+caiu|lentid[aã]o|lenta|inst[aá]vel|oscila)/i;
  if (supportRegex.test(normalized)) return 'diagnostico';

  return 'nova_mensagem';
}

const atendimentoItem = $('Polling - Preparar Mensagens').item.json ?? {};
const atendimento = atendimentoItem.atendimentoInfo ?? {};
const response = $input.first().json ?? {};
const messages = Array.isArray(response.data) ? response.data : [];

const inbound = messages
  .filter((message) => isInbound(message) && extractText(message))
  .sort((a, b) => Date.parse(a?.createdAt ?? a?.data ?? 0) - Date.parse(b?.createdAt ?? b?.data ?? 0));

const latest = inbound[inbound.length - 1];
if (!latest) {
  return [];
}

const messageText = extractText(latest);
const atendimentoId = (atendimento._id ?? atendimentoItem.pollRouteId ?? '').toString();
const contactPhone = (atendimento.canal_cliente ?? atendimentoItem.contactPhoneRaw ?? '').toString().replace(/@c\.us$/i, '');
const contactName = (atendimento.id_cliente?.nome ?? atendimento.id_user?.nome ?? atendimentoItem.contactName ?? 'Cliente').toString();
const documento = normalizeDocument(atendimento.id_cliente?.cpf_cnpj ?? atendimentoItem.documento ?? '');
const event = classifyEvent(messageText);

return [{
  json: {
    source: 'polling',
    event,
    eventType: event,
    atendimentoId,
    customerServiceId: atendimentoId,
    protocolo: (atendimento.protocolo ?? atendimentoItem.protocolo ?? '').toString(),
    telefone: contactPhone,
    contactPhoneRaw: contactPhone,
    contactName,
    contato: {
      nome: contactName,
      celularCompleto: contactPhone,
    },
    contact: {
      name: contactName,
      phone: contactPhone,
    },
    mensagem: {
      texto: messageText,
    },
    texto: messageText,
    messageText,
    messageId: (latest._id ?? '').toString(),
    messageTimestamp: (latest.createdAt ?? latest.data ?? new Date().toISOString()).toString(),
    documento,
    cpf_cnpj: documento,
    rawPayload: {
      pollingMessage: latest,
      atendimento,
    },
  },
  pairedItem: 0,
}];

function classifyEvent(text) {
  const normalized = (text ?? '').toString().toLowerCase();
  const financeRegex = /(2\s*via|segunda\s*via|boleto|pix|fatura|linha\s+digit[aá]vel|c[oó]digo\s+pix|copia\s+e\s+cola|copiar\s+e\s+colar)/i;
  if (financeRegex.test(normalized)) return 'segunda_via';

  const supportRegex = /(sem\s+internet|sem\s+conex[aã]o|sem\s+sinal|sem\s+acesso|internet\s+caiu|lentid[aã]o|lenta|inst[aá]vel|oscila)/i;
  if (supportRegex.test(normalized)) return 'diagnostico';

  return 'nova_mensagem';
}

const message = $('Polling - Extrair Cliente OPA').item.json;
const atendimento = message.atendimentoInfo ?? {};
const contactsResponse = $input.first().json ?? {};
const contacts = Array.isArray(contactsResponse.data) ? contactsResponse.data : [];
const contact = contacts[0] ?? {};
const phones = Array.isArray(contact.fones) ? contact.fones : [];
const phone = phones.find((item) => item?.whatsapp) ?? phones.find((item) => item?.celular) ?? phones[0] ?? {};
const contactPhone = (phone.numero ?? '').toString();
const contactName = (contact.nome ?? atendimento.id_cliente?.nome ?? 'Desconhecido').toString();
const messageText = (message.pollMessageText ?? '').toString();
const event = classifyEvent(messageText);
const atendimentoId = (atendimento._id ?? message.pollRouteId ?? '').toString();

const body = {
  source: 'polling',
  event,
  eventType: event,
  atendimentoId,
  customerServiceId: atendimentoId,
  telefone: contactPhone,
  contactPhoneRaw: contactPhone,
  contato: {
    nome: contactName,
    celularCompleto: contactPhone,
  },
  contact: {
    name: contactName,
    phone: contactPhone,
  },
  mensagem: {
    texto: messageText,
  },
  texto: messageText,
  messageId: (message.pollMessageId ?? '').toString(),
  messageTimestamp: (message.pollMessageTimestamp ?? new Date().toISOString()).toString(),
  rawPayload: {
    pollingMessage: message.rawMessage ?? {},
    atendimento,
    contato: contact,
  },
};

return [{
  json: {
    ...body,
    body,
    customerServiceId: atendimentoId,
    messageText,
  },
  pairedItem: 0,
}];

const prep = $('R4 - Prep Fatura').first().json;
const result = $input.first().json ?? {};
const faturas = result.data?.registros ?? result.registros ?? [];
const total = parseInt(result.data?.total ?? result.total ?? faturas.length ?? 0);
const contratosAtivos = prep.contratosAtivos ?? [];
const contratoSelecionado = prep.contratoSelecionado ?? contratosAtivos[0] ?? null;

function formatarDataBr(date) {
  return `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}`;
}

function parseDateOnly(raw) {
  const text = (raw ?? '').toString().slice(0, 10);
  if (!text || text === '0000-00-00') return null;
  const date = new Date(`${text}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

const candidatas = faturas
  .map(fatura => {
    const vencDate = parseDateOnly(fatura.data_vencimento);
    if (!vencDate) return null;

    const diasAteVenc = Math.ceil((vencDate - hoje) / 86400000);

    return {
      contratoId: (fatura.id_contrato ?? fatura.id_cliente_contrato ?? contratoSelecionado?.id ?? '').toString(),
      plano: contratoSelecionado?.plano ?? '',
      idFatura: (fatura.id ?? '').toString(),
      valorFatura: (fatura.valor ?? '').toString(),
      vencimento: (fatura.data_vencimento ?? '').toString(),
      linhaDigitavel: (fatura.linha_digitavel ?? '').toString(),
      diasAteVenc,
      vencTimestamp: vencDate.getTime(),
      dataDisponivelEnvio: formatarDataBr(new Date(vencDate.getTime() - (10 * 86400000))),
    };
  })
  .filter(Boolean)
  .sort((a, b) => a.vencTimestamp - b.vencTimestamp);

if (!candidatas.length) {
  return [{ json: {
    atendimentoId: prep.atendimentoId,
    clienteNome: prep.clienteNome ?? '',
    plano: '',
    statusFatura: 'SEM_FATURA',
    totalFaturas: total,
    idFatura: '',
    contratosAtivosTotal: contratosAtivos.length,
    faturasElegiveisTotal: 0,
  }}];
}

const prontas = candidatas.filter(fatura => fatura.diasAteVenc <= 10);
const futuras = candidatas.filter(fatura => fatura.diasAteVenc > 10);
const selecionada = (prontas[0] ?? futuras[0]) || null;
const statusFatura = prontas.length ? 'PRONTA' : 'ANTES_JANELA';

return [{ json: {
  atendimentoId: prep.atendimentoId,
  clienteNome: prep.clienteNome ?? '',
  clienteId: prep.clienteId ?? '',
  plano: selecionada?.plano ?? '',
  statusFatura,
  totalFaturas: total,
  idFatura: selecionada?.idFatura ?? '',
  contratoId: selecionada?.contratoId ?? '',
  valorFatura: selecionada?.valorFatura ?? '',
  vencimento: selecionada?.vencimento ?? '',
