  triageRoute: route,
  triageNeedsDocument: needsDocument,
  triageConfidence: (out.confidence ?? '').toString(),
  operationalText: directReply ? replyText : (merged.operationalText ?? ''),
  triageDirectReply: directReply,
  pendingIntent: persistedIntent || merged.pendingIntent || '',
}}];

const item = $input.first().json ?? {};
const messageText = (item.mensagemTexto ?? item.messageText ?? item.body?.mensagem?.texto ?? item.body?.texto ?? item.texto ?? '').toString().trim();
const contratos = Array.isArray(item.contratosAtivos) ? item.contratosAtivos : [];
const selected = item.contratoSelecionado ?? null;
const luizaUserPrompt = [
  `Mensagem do cliente: ${messageText || '(vazia)'}`,
  `Cliente: ${(item.clienteNome ?? 'Cliente').toString()}`,
  `Quantidade de contratos ativos: ${contratos.length}`,
  `Contrato ja selecionado: ${selected ? 'sim' : 'nao'}`,
  `Contrato atual: ${selected ? `${selected.id} - ${selected.plano || ''}` : 'nenhum'}`,
].join('\n');
return [{ json: { ...item, luizaUserPrompt } }];

const original = $('R4 - Luiza - Preparar Prompt').first().json ?? {};
const item = $input.first().json ?? {};
const out = item.output ?? {};
const preferred = (out.preferredPaymentMethod ?? 'auto').toString().toLowerCase();

return [{
  json: {
    ...original,
    ...item,
    preferredPaymentMethod: ['pix', 'boleto'].includes(preferred) ? preferred : 'auto',
    financeAiConfidence: (out.confidence ?? '').toString(),
    financeAiIntent: (out.customerIntent ?? '').toString(),
  },
  pairedItem: 0,
}];
